<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';
use App\Core\Database;use App\Services\RandomPairingService;use App\Services\LiveDisplaySessionService;
$p=Database::connection();$token=trim((string)($_GET['token']??$_POST['token']??''));$link=RandomPairingService::byToken($p,$token);if(!$link){http_response_code(403);exit('This Emcee Match Link is invalid, expired, confirmed or revoked.');}$round=(int)$link['round_id'];$test=$link['data_mode']==='test';$pre=$test?'bdc_test_':'bdc_';$q=$p->prepare("SELECT r.*,e.name event_name FROM {$pre}scoring_rounds r JOIN {$pre}events e ON e.id=r.event_id WHERE r.id=:r");$q->execute(['r'=>$round]);$r=$q->fetch();if(!$r){http_response_code(404);exit('Final round not found.');}$notice='';$error='';$autoReveal=false;
if($_SERVER['REQUEST_METHOD']==='POST'){try{$action=(string)($_POST['action']??'');if($action==='randomize'){RandomPairingService::randomize($p,$round,$test,null);$s=LiveDisplaySessionService::forEvent($p,(int)$r['event_id'],$test);if(!$s)throw new RuntimeException('Ask the administrator to generate the Live Display link first.');LiveDisplaySessionService::effect($p,(int)$r['event_id'],$test,'countdown',0);$autoReveal=true;$notice='Random match secured. Projector countdown started: 5, 4, 3, 2, 1.';}elseif($action==='reveal'){LiveDisplaySessionService::update($p,(int)$r['event_id'],$test,['round_id'=>$round,'screen_type'=>'matching'],0);LiveDisplaySessionService::effect($p,(int)$r['event_id'],$test,'none',0);$notice='Countdown complete. Pairings revealed without an automatic celebration effect.';}elseif(in_array($action,['hearts','balloons','heart_smiles','finger_hearts'],true)){LiveDisplaySessionService::effect($p,(int)$r['event_id'],$test,$action,0);$notice=['hearts'=>'Hearts','balloons'=>'Balloons','heart_smiles'=>'Smiling Hearts','finger_hearts'=>'Korean Finger Hearts'][$action].' sent to projection.';}elseif($action==='clear'){LiveDisplaySessionService::effect($p,(int)$r['event_id'],$test,'none',0);$notice='Projection effect cleared.';}}catch(Throwable $e){$error=$e->getMessage();}}
if($autoReveal){LiveDisplaySessionService::update($p,(int)$r['event_id'],$test,['round_id'=>$round,'screen_type'=>'holding'],0);}
$pairs=$p->prepare("SELECT fp.pair_number,fp.pairing_status,l.bib_number leader_bib,l.display_name leader_name,f.bib_number follower_bib,f.display_name follower_name FROM {$pre}scoring_final_pairs fp JOIN {$pre}scoring_entries l ON l.id=fp.leader_entry_id LEFT JOIN {$pre}scoring_entries f ON f.id=fp.follower_entry_id WHERE fp.round_id=:r ORDER BY fp.pair_number");$pairs->execute(['r'=>$round]);$pairs=$pairs->fetchAll();
$pairState=array_map(static fn(array $pair):array=>['pair_number'=>(int)$pair['pair_number'],'leader_bib'=>(int)$pair['leader_bib'],'leader_name'=>(string)$pair['leader_name'],'follower_bib'=>(int)($pair['follower_bib']??0),'follower_name'=>(string)($pair['follower_name']??''),'status'=>(string)$pair['pairing_status']],$pairs);
$pairStateHash=hash('sha256',json_encode($pairState,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
if($_SERVER['REQUEST_METHOD']==='GET'&&($_GET['format']??'')==='json'){header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode(['ok'=>true,'hash'=>$pairStateHash,'pairs'=>$pairState],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
if($autoReveal):?><form id="autoReveal" method="post" style="display:none"><input type="hidden" name="token" value="<?=e($token)?>"><input type="hidden" name="action" value="reveal"></form><script>let seconds=5;addEventListener('DOMContentLoaded',()=>{const box=document.createElement('div');box.className='alert alert-warning fw-bold';box.innerHTML='Projector countdown: <span id="revealCountdown">5</span>';document.querySelector('main').prepend(box);const start=document.querySelector('button[value="randomize"]');if(start){start.disabled=true;start.textContent='Reveal in progress…';}});const revealTimer=setInterval(()=>{seconds--;const el=document.getElementById('revealCountdown');if(el)el.textContent=String(Math.max(1,seconds));if(seconds<=0){clearInterval(revealTimer);document.getElementById('autoReveal').submit();}},1000);</script><?php endif;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Emcee Random Match</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#0b1220;color:#fff}.card{color:#172033}.match{font-size:1.05rem}.effect-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.6rem}@media(min-width:768px){.effect-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}</style></head><body><main class="container py-4" style="max-width:900px"><div class="text-warning fw-bold"><?=$test?'TESTING · ':''?>EMCEE PRESENTATION</div><h1>Random Final Match</h1><p><?=e($r['event_name'])?> · <?=e(ucwords(str_replace('_',' ',$r['division'])))?></p><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card mb-3"><div class="card-body"><form method="post" onsubmit="return confirm('Generate a new secure random draft match and show it on projection?');"><input type="hidden" name="token" value="<?=e($token)?>"><button class="btn btn-warning btn-lg w-100" name="action" value="randomize">🎲 Start Random Match</button></form><div class="effect-grid mt-3"><?php foreach(['hearts'=>['💖','Hearts','danger'],'balloons'=>['🎈','Balloons','primary'],'heart_smiles'=>['🥰','Smiling Hearts','warning'],'finger_hearts'=>['🫰','Korean Finger Hearts','dark']] as $effectAction=>$effectMeta):?><form method="post"><input type="hidden" name="token" value="<?=e($token)?>"><button class="btn btn-<?=$effectMeta[2]?> w-100 h-100" name="action" value="<?=$effectAction?>"><span class="fs-4 d-block"><?=$effectMeta[0]?></span><?=$effectMeta[1]?></button></form><?php endforeach;?></div><form method="post" class="mt-2"><input type="hidden" name="token" value="<?=e($token)?>"><button class="btn btn-outline-secondary w-100" name="action" value="clear">Clear Effect</button></form><div class="small text-muted mt-3"><strong>Random Matching Method: Secure Fisher–Yates Shuffle</strong><br>Leaders remain in bib order while Followers are securely and randomly shuffled, giving every Follower an equal chance of matching with any Leader.</div></div></div><div class="card"><div class="card-body"><h2 class="h5">Current Draft Matches</h2><?php if(!$pairs):?><p class="text-muted">Press Start Random Match.</p><?php else:foreach($pairs as $x):?><div class="match border-bottom py-2"><strong>Couple <?=$x['pair_number']?></strong> · Bib <?=$x['leader_bib']?> <?=e($x['leader_name'])?> + Bib <?=$x['follower_bib']?> <?=e($x['follower_name'])?></div><?php endforeach;endif;?></div></div></main><script>(function(){let hash=<?=json_encode($pairStateHash)?>,busy=false;setInterval(async()=>{if(document.hidden||busy)return;busy=true;try{const url=new URL(location.href);url.searchParams.set('format','json');const response=await fetch(url,{cache:'no-store',headers:{Accept:'application/json'}}),data=await response.json();if(data.ok&&data.hash!==hash)location.reload();}catch(error){}finally{busy=false}},1500)})();</script></body></html>
